(33, 'pinedapaola679@gmail.com', 'Recuperar Contraseña', '<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <style>\n    body {\n      display: flex;\n      justify-content: center;\n      align-items: center;\n      height: 100vh;\n      margin: 0;\n      font-family: \'Arial\', sans-serif;\n      font-size: 13px;\n      color: #000;\n      background-color: hsl(0,0%,88.9%);\n    }\n\n    .email-wrapper {\n      width: 100%;\n      padding: 20px;\n      background-color: hsl(0,0%,88.9%);;\n      box-sizing: border-box;\n    }\n\n    .container {\n      width: 100%;\n      max-width: 600px;\n      margin: 0 auto;\n      background-color: #ffffff;\n      padding: 30px;\n      border-radius: 8px;\n      box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\n      text-align: center;\n      box-sizing: border-box;\n    }\n\n    .logo {\n      max-width: 150px;\n      max-height: 100px;\n      border-radius: 8px;\n      margin-bottom: 20px;\n    }\n\n    h1 {\n      color: #000;\n      font-size: 24px;\n      margin-bottom: 20px;\n    }\n\n    p {\n      color: #000;\n      font-size: 16px;\n      line-height: 1.5;\n    }\n\n    .button {\n      display: inline-block;\n      padding: 16px 32px;\n      margin-top: 10px;\n      background-color: hsl(201,41.5%,46.3%);\n      color: #ffffff;\n      text-decoration: none;\n      border-radius: 4px;\n      font-size: 18px;\n    }\n\n    .button:hover {\n      background-color: hsl(201,41.5%,38.3%);\n    }\n\n    .footer {\n      margin-top: 30px;\n      font-size: 12px;\n      text-align: center;\n    }\n\n    .footer a {\n      text-decoration: none;\n    }\n\n    @media only screen and (max-width: 600px) {\n      .container {\n        padding: 20px;\n      }\n\n      .logo {\n        max-width: 160px;\n        max-height: 100px;\n      }\n\n      body {\n        font-size: 15px;\n      }\n    }\n\n    @media only screen and (max-width: